import { zodResolver } from "@hookform/resolvers/zod";
import { useState } from "react";
import { Controller, useForm } from "react-hook-form";
import { z } from "zod";
import { parseCents } from "../../lib/money";
import { Button } from "../ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "../ui/dialog";
import { Field, FieldError, FieldGroup, FieldLabel } from "../ui/field";
import { Input } from "../ui/input";

const ledgerSchema = z.object({
  amount: z.string().refine((value) => parseCents(value) > 0, {
    message: "Enter an amount",
  }),
  memo: z.string(),
});

type LedgerValues = z.infer<typeof ledgerSchema>;

const BLANK_LEDGER: LedgerValues = { amount: "", memo: "" };

export function LedgerDialog({
  title,
  description,
  submitLabel,
  pending,
  onSubmit,
}: {
  title: string;
  description: string;
  submitLabel: string;
  pending: boolean;
  onSubmit: (
    input: { amountCents: number; memo: string | null },
    close: () => void
  ) => void;
}) {
  const [open, setOpen] = useState(false);
  const form = useForm<LedgerValues>({
    resolver: zodResolver(ledgerSchema),
    defaultValues: BLANK_LEDGER,
  });

  function close() {
    form.reset(BLANK_LEDGER);
    setOpen(false);
  }

  return (
    <Dialog
      onOpenChange={(next) => {
        setOpen(next);
        if (!next) {
          form.reset(BLANK_LEDGER);
        }
      }}
      open={open}
    >
      <DialogTrigger render={<Button size="sm" variant="outline" />}>
        {title}
      </DialogTrigger>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
